# Let me try DIFFERENT periods and see which one matches TEST
DEMO_18 = [9, 9, 6, 1, 4, 8, 6, 6, 4, 8, 4, 4, 3, 2, 6, 6, 4, 2]

test_nonzero_k = {3:1, 9:8, 18:9, 19:9, 24:6, 25:6, 26:4, 27:4, 28:4, 29:4, 35:2}

# Try different periods and count mismatches
for period in [9, 18, 19, 23, 26, 27]:
    mismatches = 0
    for k in sorted(test_nonzero_k.keys()):
        expected = None
        # Get value from first position of DEMO pattern for this period
        if k < period:
            expected = DEMO_18[k]
        elif period <= k < period*2:
            expected = DEMO_18[k - period + 19]  # Use wrap
        elif k >= period*2:
            # For k >= period*2, we use modulo
            expected = DEMO_18[k % period]

        if expected != test_nonzero_k[k]:
            mismatches += 1
    print(f"Period {period}: {mismatches} mismatches")

# Hmm, let me check if the rule is about a DIFFERENT C array for TEST 
# not derived from DEMO_18

# Maybe TEST just uses a simple pattern without DEMO influence
# Let me see if k value directly relates to value

print("\n\nTEST Anti-diagonal values:")
for k in sorted(test_nonzero_k.keys()):
    print(f"  k={k}: value={test_nonzero_k[k]}")

# Check against k mod some period
for mod in range(3, 40):
    matches = 0
    for k, val in test_nonzero_k.items():
        if k % mod < 18:  # Only check against DEMO_18 if index valid
            expected = DEMO_18[k % mod]
            if expected == val:
                matches += 1
    if matches == len(test_nonzero_k):
        print(f"\nFound perfect match with period {mod}!")

# Or maybe it's NOT period-based at all
# Maybe each anti-diagonal has its own value from DEMO's k position

# Wait - let me check if DEMO's ORIGINAL C_DEMO works better
C_DEMO = [9, 9, 6, 1, 4, 8, 6, 6, 4, 8, 4, 4, 3, 2, 6, 6, 4, 2, 3, 9, 9, 6, 1]

print("\n\nTEST vs C_DEMO period 23:")
mismatches = 0
for k, val in test_nonzero_k.items():
    expected = C_DEMO[k % 23]
    if expected == val:
        print(f"  k={k}: C_DEMO[{k%23}]={expected} ✓")
    else:
        print(f"  k={k}: C_DEMO[{k%23}]={expected}, TEST={val} ✗")
        mismatches += 1

print(f"\nTotal mismatches: {mismatches}")

